SET standard_conforming_strings = on;
SET search_path = pg_catalog, public;

CREATE TABLE "public"."projects" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."projects_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "project_name" text NOT NULL,
  "project_name_bn" text,
  "main_gate_phone" text,
  "admin_phone" text,
  "admin_whatsapp" text,
  "is_active" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "address" text,
  "address_bn" text,
  "admin_name" text,
  "division" text,
  "district" text,
  "thana" text,
  "division_id" text,
  "district_id" text,
  "upazila_id" text,
  "union_id" text,
  "village" text,
  "street" text,
  "start_date" text,
  "status" text DEFAULT 'Active'::text,
  "deleted_at" timestamp with time zone,
  "deleted_by" uuid,
  "meeting_attendance_enabled" boolean DEFAULT true NOT NULL
) USING "heap";
ALTER TABLE "public"."projects" OWNER TO "postgres";
COMMENT ON COLUMN "public"."projects"."meeting_attendance_enabled" IS 'TRUE when an operationally active project participates in Meeting Attendance; FALSE hides it only from the Meeting Attendance scope and calculations.';
